import React from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

// Gambar komik sudah tertanam di file ini (tidak perlu unggah gambar terpisah)
const IMG = "data:image/jpeg;base64,";

const W = 1080;
const H = 1920;

// Kamera: t = detik, x/y = titik fokus (0-1 pada gambar), z = zoom
const CAM = [
  { t: 0, x: 0.5, y: 0.5, z: 1.0 },
  { t: 4.5, x: 0.5, y: 0.5, z: 1.0 },
  { t: 8, x: 0.5, y: 0.25, z: 1.25 },
  { t: 14, x: 0.3, y: 0.3, z: 2.0 },
  { t: 20, x: 0.52, y: 0.34, z: 2.1 },
  { t: 26, x: 0.8, y: 0.3, z: 2.0 },
  { t: 30.5, x: 0.5, y: 0.53, z: 1.6 },
  { t: 35.5, x: 0.3, y: 0.78, z: 1.8 },
  { t: 42, x: 0.85, y: 0.8, z: 2.2 },
  { t: 48, x: 0.5, y: 0.82, z: 1.3 },
  { t: 53, x: 0.5, y: 0.5, z: 1.0 },
  { t: 59, x: 0.5, y: 0.5, z: 1.0 },
];

// Narasi (teks muncul kata per kata)
const LINES = [
  { s: 0.3, e: 4.5, text: "Pernah nggak sih, lihat desa mendadak ribut gara-gara pilkades?" },
  { s: 4.5, e: 9, text: "Padahal sama-sama tetangga, dulu sering ngopi bareng." },
  { s: 9, e: 14, text: "Tim satu, tim dua, semua merasa paling benar." },
  { s: 14, e: 19.5, text: "Saling tuding, saling sindir, sampai dibilang hoaks dan dibayar." },
  { s: 19.5, e: 25.5, text: "Yang tadinya akur, sekarang nggak saling sapa. Tenaga habis buat ribut." },
  { s: 25.5, e: 30.5, text: "Salah pilih? Kurang ajar? Semua kata keluar di tengah jalan." },
  { s: 30.5, e: 35, text: "Terus, setelah hasilnya disahkan, apa yang terjadi?" },
  { s: 35, e: 41, text: "Yang menang duduk manis, ngopi santai di ruangan ber-AC." },
  { s: 41, e: 47, text: "Sementara warga yang dulu dibela mati-matian, menunggu di luar pintu." },
  { s: 47, e: 52, text: "Janji kampanye? Tinggal cerita. Kita pun dilupakan." },
  { s: 52, e: 58.5, text: "Lain kali, bela programnya, bukan orangnya. Boleh beda pilihan, jangan sampai beda kampung." },
];

const ease = Easing.inOut(Easing.cubic);

export const Video: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();
  const t = frame / fps;

  // ----- kamera -----
  let i = 0;
  for (let k = 0; k < CAM.length - 1; k++) {
    if (t >= CAM[k].t) i = k;
  }
  const a = CAM[i];
  const b = CAM[Math.min(i + 1, CAM.length - 1)];
  const p = interpolate(t, [a.t, b.t], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: ease,
  });
  const drift = 1 + 0.015 * Math.sin(t * 0.9);
  const z = (a.z + (b.z - a.z) * p) * drift;
  const fx = a.x + (b.x - a.x) * p;
  const fy = a.y + (b.y - a.y) * p;

  let tx = W / 2 - fx * W * z;
  let ty = H / 2 - fy * H * z;
  tx = Math.min(0, Math.max(W - W * z, tx));
  ty = Math.min(0, Math.max(H - H * z, ty));

  // ----- teks narasi -----
  const line = LINES.find((l) => t >= l.s && t < l.e);
  const fade = interpolate(frame, [0, 12, durationInFrames - 15, durationInFrames], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: "#000", overflow: "hidden" }}>
      <div style={{ opacity: fade, width: W, height: H, position: "relative" }}>
        <img
          src={IMG}
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: W,
            height: H,
            transformOrigin: "0 0",
            transform: `translate(${tx}px, ${ty}px) scale(${z})`,
          }}
        />

        {/* bayangan bawah supaya teks mudah dibaca */}
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            bottom: 0,
            height: 700,
            background: "linear-gradient(to top, rgba(0,0,0,0.75), rgba(0,0,0,0))",
          }}
        />

        {line && <Caption line={line} frame={frame} fps={fps} />}
      </div>
    </AbsoluteFill>
  );
};

const Caption: React.FC<{
  line: { s: number; e: number; text: string };
  frame: number;
  fps: number;
}> = ({ line, frame, fps }) => {
  const words = line.text.split(" ");
  const start = line.s * fps;
  const span = (line.e - line.s) * fps * 0.85;
  const step = span / words.length;

  let current = 0;
  words.forEach((_, idx) => {
    if (frame >= start + idx * step) current = idx;
  });

  return (
    <div
      style={{
        position: "absolute",
        left: 50,
        right: 50,
        bottom: 150,
        textAlign: "center",
        fontFamily: "Arial Black, Impact, Helvetica, sans-serif",
        fontWeight: 900,
        fontSize: 68,
        lineHeight: 1.25,
      }}
    >
      {words.map((w, idx) => {
        const at = start + idx * step;
        if (frame < at) return null;
        const pop = interpolate(frame, [at, at + 6], [0.7, 1], {
          extrapolateRight: "clamp",
          easing: Easing.out(Easing.back(2)),
        });
        const isCur = idx === current;
        return (
          <span
            key={idx}
            style={{
              display: "inline-block",
              marginRight: 16,
              transform: `scale(${pop})`,
              color: isCur ? "#FFD600" : "#FFFFFF",
              WebkitTextStroke: "10px #000",
              paintOrder: "stroke fill",
              textShadow: "0 6px 14px rgba(0,0,0,0.6)",
            }}
          >
            {w}
          </span>
        );
      })}
    </div>
  );
};
